void th_debug_notify_filament(const char *op, uint8_t slot, uint8_t present_mask, const char *step_state)
{
  if ((op == NULL) || (step_state == NULL))
  {
    return;
  }
  const uint8_t norm_slot = (uint8_t)(slot & 0x03U);
  active_extruder = norm_slot;
  s_th_dbg_state.slot = norm_slot;
  s_th_dbg_state.active_slot = norm_slot;
  s_th_dbg_state.filament_mask = present_mask;
  s_th_dbg_state.op_str = op;
  s_th_dbg_state.step_str = step_state;
  char state_kv[128];
  th_dbg_format_filament_kv(state_kv, sizeof(state_kv));
  const uint8_t cmd_id = (strcmp(op, "SELECT") == 0) ? MINIMC_CMD_SLOT_SELECT : MINIMC_CMD_FILAMENT_CONTROL;
  const th_dbg_meta_t st_meta = { "STATE", "TH", s_th_dbg_state.last_seq, cmd_id, "OK" };
  th_dbg_emit(&st_meta, state_kv);
}

/**
 * @brief 解析接收耗材命令帧的操作类型字符串（SELECT/LOAD/UNLOAD）。
 */
static const char *th_dbg_resolve_filament_op(uint8_t cmd_id, const uint8_t *frame, uint16_t plen)
{
  if (cmd_id == MINIMC_CMD_SLOT_SELECT)
  {
    if ((plen > 1U) && (frame[13] == 1U))
    {
      return "LOAD";
    }
    if ((plen > 1U) && (frame[13] == 2U))
    {
      return "UNLOAD";
    }
    return "SELECT";
  }
  const bool is_unload = ((plen > 1U) &&
                          ((frame[13] == 2U) || ((plen < 4U) && (frame[13] == 1U))));
  return is_unload ? "UNLOAD" : "LOAD";
}

/**
 * @brief 格式化 TH 合法接收帧的关键字段字符串。
 */
static void th_dbg_format_rx_kv(const uint8_t *frame, uint16_t len, char *rx_kv, size_t cap)
{
  const uint8_t cmd_id = frame[5];
  const uint16_t plen = (uint16_t)frame[10] | (uint16_t)((uint16_t)frame[11] << 8U);
  if ((cmd_id == MINIMC_CMD_SET_TEMP) && (plen >= 2U))
  {
    const int16_t n_set = (int16_t)((uint16_t)frame[12] | ((uint16_t)frame[13] << 8U));
    (void)snprintf(rx_kv, cap, "len=%u nozzle_set=%d", (unsigned int)len, (int)n_set);
  }
  else if ((cmd_id == MINIMC_CMD_FILAMENT_CONTROL) ||
           (cmd_id == MINIMC_CMD_SLOT_SELECT) ||
           (cmd_id == MINIMC_CMD_FILAMENT_LEGACY))
  {
    const uint8_t slot = (plen > 0U) ? (uint8_t)(frame[12] & 0x03U) : 0U;
    const char *op_s = th_dbg_resolve_filament_op(cmd_id, frame, plen);
    (void)snprintf(rx_kv, cap, "len=%u op=%s slot=%u", (unsigned int)len, op_s, (unsigned int)slot);
  }
  else if (cmd_id == MINIMC_CMD_MOTION_STOP)
  {
    (void)snprintf(rx_kv, cap, "len=%u op=QUICKSTOP", (unsigned int)len);
  }
  else if ((cmd_id == MINIMC_CMD_GCODE_EXEC) && (plen >= 2U))
  {
    (void)snprintf(rx_kv, cap, "len=%u gcode_len=%u", (unsigned int)len, (unsigned int)frame[12]);
  }
  else
  {
    (void)snprintf(rx_kv, cap, "len=%u", (unsigned int)len);
  }
}

static void th_dbg_handle_valid_rx_frame(const uint8_t *frame, uint16_t len)
{
  if ((frame == NULL) || (len < MINIMC_HEADER_SIZE))
  {
    return;
  }
  const uint8_t dst_id = frame[3];
  const uint8_t flags = frame[4];
  const bool valid_dst = ((dst_id == MINIMC_NODE_TH) || (dst_id == MINIMC_NODE_BROADCAST));
  if (((flags & MINIMC_FLAG_PROTO_V2) == 0U) || ((flags & MINIMC_FLAG_IS_RESPONSE) != 0U) || (!valid_dst))
  {
    th_dbg_log_frame_err(frame, "BAD_FRAME", 0x02U);
    return;
  }
  const uint8_t cmd_id = frame[5];
  const uint16_t seq = (uint16_t)frame[8] | (uint16_t)((uint16_t)frame[9] << 8U);
  s_th_dbg_state.last_seq = seq;

  char rx_kv[96];
  th_dbg_format_rx_kv(frame, len, rx_kv, sizeof(rx_kv));
  const th_dbg_meta_t rx_meta = { "RX", th_dbg_node_name(dst_id), seq, cmd_id, "OK" };
  th_dbg_emit(&rx_meta, rx_kv);
}

static bool th_dbg_rx_step_sof(uint8_t byte)
{
  if (s_dbg_rx.state == TH_DBG_PARSE_IDLE)
  {
    if (byte == MINIMC_SOF_1)
    {
      s_dbg_rx.buf[0] = byte;
      s_dbg_rx.idx = 1U;
      s_dbg_rx.state = TH_DBG_PARSE_SOF2;
    }
    return true;
  }
  if (s_dbg_rx.state == TH_DBG_PARSE_SOF2)
  {
    if (byte == MINIMC_SOF_2)
    {
      s_dbg_rx.buf[1] = byte;
      s_dbg_rx.idx = 2U;
      s_dbg_rx.state = TH_DBG_PARSE_HEADER;
    }
    else if (byte != MINIMC_SOF_1)
    {
      th_dbg_rx_reset();
    }
    return true;
  }
  return false;
}

static void th_dbg_finish_rx_crc(void)
{
  const uint16_t body_len = (uint16_t)(s_dbg_rx.expected_len - MINIMC_CRC_SIZE);
  const uint16_t calc_c = minimc_crc16(s_dbg_rx.buf, body_len);
  const uint16_t rx_c = (uint16_t)s_dbg_rx.buf[body_len] |
                        (uint16_t)((uint16_t)s_dbg_rx.buf[body_len + 1U] << 8U);
  if (calc_c == rx_c)
  {
    th_dbg_handle_valid_rx_frame(s_dbg_rx.buf, s_dbg_rx.expected_len);
  }
  else
  {
    th_dbg_log_frame_err(s_dbg_rx.buf, "CRC_ERR", 0x01U);
  }
  th_dbg_rx_reset();
}

static void th_dbg_observe_rx_byte(uint8_t byte)
{
  const uint32_t now_ms = get_tick_count();
  if ((s_dbg_rx.state != TH_DBG_PARSE_IDLE) &&
      ((uint32_t)(now_ms - s_dbg_rx.last_byte_ms) > TH_DBG_PARSE_TIMEOUT_MS))
  {
    th_dbg_rx_reset();
  }
  s_dbg_rx.last_byte_ms = now_ms;
  if (th_dbg_rx_step_sof(byte))
  {
    return;
  }
  s_dbg_rx.buf[s_dbg_rx.idx] = byte;
  s_dbg_rx.idx++;

  if ((s_dbg_rx.state == TH_DBG_PARSE_HEADER) && (s_dbg_rx.idx == MINIMC_HEADER_SIZE))
  {
    const uint16_t plen = (uint16_t)s_dbg_rx.buf[10] | (uint16_t)((uint16_t)s_dbg_rx.buf[11] << 8U);
    if (plen > MINIMC_MAX_PAYLOAD_SIZE)
    {
      th_dbg_log_frame_err(s_dbg_rx.buf, "BAD_FRAME", 0x02U);
      th_dbg_rx_reset();
      return;
    }
    s_dbg_rx.expected_len = (uint16_t)(MINIMC_HEADER_SIZE + plen + MINIMC_CRC_SIZE);
    s_dbg_rx.state = (plen == 0U) ? TH_DBG_PARSE_CRC : TH_DBG_PARSE_PAYLOAD;
  }
  else if ((s_dbg_rx.state == TH_DBG_PARSE_PAYLOAD) &&
           (s_dbg_rx.idx == (uint16_t)(s_dbg_rx.expected_len - MINIMC_CRC_SIZE)))
  {
    s_dbg_rx.state = TH_DBG_PARSE_CRC;
  }
  else if ((s_dbg_rx.state == TH_DBG_PARSE_CRC) && (s_dbg_rx.idx >= s_dbg_rx.expected_len))
  {
    th_dbg_finish_rx_crc();
  }
}

static void ring_push(ring_buf_t *r, const uint8_t *data, uint16_t len)
{
    if ((r == NULL) || (data == NULL) || (len == 0U))
    {
        return;
    }
    for (uint16_t i = 0U; i < len; ++i)
    {
        const uint16_t next_head = (uint16_t)((r->head + 1U) % AP_RING_CAPACITY);
        if (next_head == r->tail)
        {
            break;
        }
        r->buf[r->head] = data[i];
        r->head = next_head;
    }
}

static bool ring_pop(ring_buf_t *r, uint8_t *out_byte)
{
    if ((r == NULL) || (out_byte == NULL) || (r->head == r->tail))
    {
        return false;
    }
    *out_byte = r->buf[r->tail];
    r->tail = (uint16_t)((r->tail + 1U) % AP_RING_CAPACITY);
    return true;
}

static void parser_init(stream_parser_t *p)
{
    if (p == NULL)
    {
        return;
    }
    p->state = PARSER_STATE_WAIT_SOF1;
    p->idx = 0U;
    p->expected_payload_len = 0U;
}

static void parser_reset(stream_parser_t *p)
{
    if (p == NULL)
    {
        return;
    }
    p->state = PARSER_STATE_WAIT_SOF1;
    p->idx = 0U;
    p->expected_payload_len = 0U;
}

static bool parser_check_header(stream_parser_t *p)
{
    if (p == NULL)
    {
        return false;
    }
    const uint8_t flags = p->buf[4];
    if ((flags & 0x0CU) != MINIMC_FLAG_PROTO_V2)
    {
        return false;
    }
    const uint16_t pay_lo = (uint16_t)p->buf[10];
    const uint16_t pay_hi = (uint16_t)p->buf[11];
    p->expected_payload_len = (uint16_t)(pay_lo | (pay_hi << 8U));
    if (p->expected_payload_len > MINIMC_MAX_PAYLOAD_SIZE)
    {
        return false;
    }
    return true;
}

static bool parser_step_sof(stream_parser_t *p, uint8_t byte)
{
    if (p->state == PARSER_STATE_WAIT_SOF1)
    {
        if (byte == MINIMC_SOF_1)
        {
            p->buf[0] = byte;
            p->idx = 1U;
            p->state = PARSER_STATE_WAIT_SOF2;
        }
        return true;
    }
    if (p->state == PARSER_STATE_WAIT_SOF2)
    {
        if (byte == MINIMC_SOF_2)
        {
            p->buf[1] = byte;
            p->idx = 2U;
            p->state = PARSER_STATE_READ_HEADER;
        }
        else if (byte != MINIMC_SOF_1)
        {
            parser_reset(p);
        }
        return true;
    }
    return false;
}

static void mc_dbg_log_frame_err(const uint8_t *hdr, const char *status_str, uint8_t err_code)
{
    if ((hdr == NULL) || (status_str == NULL))
    {
        return;
    }
    char kv[32];
    (void)snprintf(kv, sizeof(kv), "err_code=0x%02X", (unsigned int)err_code);
    const uint16_t seq = (uint16_t)hdr[8] | (uint16_t)((uint16_t)hdr[9] << 8U);
    const mc_dbg_meta_t meta = {
        "ERR",
        mc_dbg_node_name(hdr[3]),
        seq,
        hdr[5],
        status_str
    };
    mc_dbg_emit(&meta, kv);
}

static bool parser_step(stream_parser_t *p, uint8_t byte, bool *out_ready)
{
    if ((p == NULL) || (out_ready == NULL))
    {
        return false;
    }
    *out_ready = false;
    if (parser_step_sof(p, byte))
    {
        return true;
    }
    p->buf[p->idx] = byte;
    p->idx++;
    if ((p->state == PARSER_STATE_READ_HEADER) && (p->idx == MINIMC_HEADER_SIZE))
    {
        if (!parser_check_header(p))
        {
            mc_dbg_log_frame_err(p->buf, "BAD_FRAME", 0x02U);
            parser_reset(p);
            return true;
        }
        p->state = (p->expected_payload_len == 0U) ? PARSER_STATE_READ_CRC : PARSER_STATE_READ_PAYLOAD;
        return true;
    }
    if ((p->state == PARSER_STATE_READ_PAYLOAD) && (p->idx == (MINIMC_HEADER_SIZE + p->expected_payload_len)))
    {
        p->state = PARSER_STATE_READ_CRC;
        return true;
    }
    if ((p->state == PARSER_STATE_READ_CRC) &&
        (p->idx == (MINIMC_HEADER_SIZE + p->expected_payload_len + MINIMC_CRC_SIZE)))
    {
        const uint16_t calc_len = (uint16_t)(MINIMC_HEADER_SIZE + p->expected_payload_len);
        const uint16_t calc_c = minimc_crc16(p->buf, calc_len);
        const uint16_t rx_c = (uint16_t)p->buf[p->idx - 2U] | (uint16_t)((uint16_t)p->buf[p->idx - 1U] << 8U);
        if (calc_c == rx_c)
        {
            *out_ready = true;
        }
        else
        {
            mc_dbg_log_frame_err(p->buf, "CRC_ERR", 0x01U);
        }
        parser_reset(p);
    }
    return true;
}

static void build_version_resp(uint16_t seq, uint8_t *out_buf, uint16_t *out_len)
{
    if ((out_buf == NULL) || (out_len == NULL))
    {
        return;
    }
    out_buf[0] = MINIMC_SOF_1;
    out_buf[1] = MINIMC_SOF_2;
    out_buf[2] = MINIMC_NODE_MC;
    out_buf[3] = MINIMC_NODE_AP;
    out_buf[4] = (uint8_t)(MINIMC_FLAG_IS_RESPONSE | MINIMC_FLAG_PROTO_V2);
    out_buf[5] = MINIMC_CMD_VERSION_REPORT;
    out_buf[6] = MINIMC_DEFAULT_HOP_LIMIT;
    out_buf[7] = MINIMC_DEFAULT_ROUTE;
    out_buf[8] = (uint8_t)(seq & 0xFFU);
    out_buf[9] = (uint8_t)((seq >> 8U) & 0xFFU);
    out_buf[10] = 0x10U;
